head.script:
// [샘플 분리]
//  _1 : disabled="true" (생성 시 고정) - @propval true / @spec1 편집 불가 / @spec2 이벤트 미발생 / @spec3 disabledClass 적용
//  _2 : disabled="false" 명시 + disabled 미설정 - @propval false(default)
//  _3 : GridView/Row/Column/Cell 4개 단위를 각각 설정 - @description| 단위별 관리
//       (4개 단위를 동시에 설정한 구성이 필요해 _1/_2 의 정적 구성과 분리)

// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > disabled]<br/>특정 Body Cell 이 아닌 Body Column 의 비활성화(disabled) 상태를 설정합니다.",
    "validation" : [
        "GridView 의 비활성화(disabled) 상태는 GridView, Row, Column, Cell 단위로 각각 관리됩니다."
    ]
}



scwin.onpageload = function () {
    // GridView / Row / Column / Cell 4개 단위에 각각 다른 값을 설정
    target1.setDisabled("grid", false);         // GridView 단위
    target1.setRowDisabled(1, true);            // Row 단위
    target1.setRowDisabled(2, false);           // Row 단위
    target1.setColumnDisabled(1, true);         // Column 단위 (col2)
    target1.setColumnDisabled(2, false);        // Column 단위 (col3)
    target1.setCellDisabled(0, "col1", true);   // Cell 단위

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 단위 상태 확인 버튼
//  - 각 단위(grid/row/column/cell)에 설정한 값이 단위별로 각각 유지되는지 조회
scwin.btn_checkUnitState_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("GridView 단위 : " + target1.getDisabled("grid"));
    bottom.setReturnValue("Row 단위 : row 1 = " + target1.getDisabled("row", 1) + " / row 2 = " + target1.getDisabled("row", 2));
    bottom.setReturnValue("Column 단위 : column 1(col2) = " + target1.getDisabled("column", 1) + " / column 2(col3) = " + target1.getDisabled("column", 2));
    bottom.setReturnValue("Cell 단위 : cell(0,col1) = " + target1.getDisabled("cell", 0, "col1"));
}



// 셀 더블클릭 시 발생 (편집 진입 여부로 각 단위 설정이 반영되는지 확인)
scwin.target1_oncelldblclick = function (row, col) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncelldblclick 발생 : Cell(" + row + "," + col + ") isEditing=" + target1.isEditing());
}
